package com.cookly.actividades;
import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import androidx.lifecycle.ViewModelProvider; import androidx.recyclerview.widget.LinearLayoutManager; import androidx.recyclerview.widget.RecyclerView; import com.cookly.R; import com.cookly.adaptadores.AdaptadorRecomendaciones; import com.cookly.utilidades.ValidadorEntrada; import com.cookly.vistasmodelos.VistaModeloMenuExpress;
public class ActividadInicio extends AppCompatActivity { private VistaModeloMenuExpress modelo; @Override public void onCreate(Bundle estado){super.onCreate(estado);setContentView(R.layout.actividad_inicio);AdaptadorRecomendaciones adaptador=new AdaptadorRecomendaciones(r->Toast.makeText(this,r.nombre,Toast.LENGTH_SHORT).show());RecyclerView lista=findViewById(R.id.listaRecetas);lista.setLayoutManager(new LinearLayoutManager(this));lista.setAdapter(adaptador);modelo=new ViewModelProvider(this).get(VistaModeloMenuExpress.class);modelo.obtenerRecomendaciones().observe(this,adaptador::actualizar);modelo.obtenerError().observe(this,mensaje->{if(mensaje!=null)Toast.makeText(this,mensaje,Toast.LENGTH_SHORT).show();});findViewById(R.id.botonMenuExpress).setOnClickListener(v->mostrarMenuExpress());} private void mostrarMenuExpress(){EditText entrada=new EditText(this);entrada.setHint("huevo, arroz, tomate");new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("Menú Express").setView(entrada).setPositiveButton("Buscar",(d,w)->buscar(entrada.getText().toString())).show();}private void buscar(String texto){java.util.List<String> ingredientes=ValidadorEntrada.separarIngredientes(texto);if(ingredientes.isEmpty()){Toast.makeText(this,"Ingresa al menos un ingrediente",Toast.LENGTH_SHORT).show();return;}modelo.buscar(ingredientes);} }
